import{_ as r,o as a,c as o,a2 as n}from"./chunks/framework.CsGzzEsd.js";const u=JSON.parse('{"title":"日本語文法の基礎","description":"","frontmatter":{"title":"日本語文法の基礎"},"headers":[],"relativePath":"jp/blogs/JLPT-N2/grammars.md","filePath":"jp/blogs/JLPT-N2/grammars.md"}'),l={name:"jp/blogs/JLPT-N2/grammars.md"};function s(d,t,e,i,g,h){return a(),o("div",null,[...t[0]||(t[0]=[n('<h1 id="日本語文法の基礎" tabindex="-1">日本語文法の基礎 <a class="header-anchor" href="#日本語文法の基礎" aria-label="Permalink to &quot;日本語文法の基礎&quot;">​</a></h1><p>N2 の文法を学ぶ前に確認しておきたい基本の文型です。以下では <strong>N</strong> を名詞、<strong>A/B</strong> を文中の各位置に入る語句として使います。</p><h2 id="a-は-b-です" tabindex="-1">A は B です <a class="header-anchor" href="#a-は-b-です" aria-label="Permalink to &quot;A は B です&quot;">​</a></h2><p><strong>規則：</strong> は は「わ」と読み、話題を示します。「A について言えば」という意味です。名詞やナ形容詞を述語にする文では、です を付けると丁寧になります。話題は必ずしも文法上の主語と同じではありません。</p><ul><li>私は留学生です。——話し手が留学生であることを述べています。</li><li>あの方は先生です。——あの人が先生であることを丁寧に述べています。</li></ul><p><strong>否定：</strong> A は B ではありません。会話では B じゃありません とも言います。</p><ul><li>私は先生ではありません。——先生であることを否定しています。</li></ul><p><strong>疑問：</strong> 丁寧な文の末尾に か を付けます。書くときの疑問符は必須ではありません。</p><ul><li>あの方は先生ですか。——あの方の職業を尋ねています。</li></ul><p><strong>述語をつなぐ：</strong> 名詞やナ形容詞の述語を次の述語につなぐときは B で を使います。この で は断定の助動詞の連用形であり、動作の場所を示す助詞ではありません。</p><ul><li>田中さんは先生で、作家です。——田中さんには二つの職業があります。</li></ul><h2 id="指示語" tabindex="-1">指示語 <a class="header-anchor" href="#指示語" aria-label="Permalink to &quot;指示語&quot;">​</a></h2><p><strong>規則：</strong> 語頭の <strong>こ</strong> は話し手の近く、<strong>そ</strong> は聞き手の近くや前に話題に出たもの、<strong>あ</strong> は両者から離れたもの、<strong>ど</strong> は疑問を表します。会話では、そ・あ が共通の記憶にあるものを指すこともあります。距離は基本的な目安です。</p><table tabindex="0"><thead><tr><th>位置</th><th>物</th><th>場所</th><th>方向／人を丁寧に指す語</th></tr></thead><tbody><tr><td>話し手の近く</td><td>これ</td><td>ここ</td><td>こちら</td></tr><tr><td>聞き手の近く</td><td>それ</td><td>そこ</td><td>そちら</td></tr><tr><td>両者から遠い</td><td>あれ</td><td>あそこ</td><td>あちら</td></tr><tr><td>疑問</td><td>どれ</td><td>どこ</td><td>どちら</td></tr></tbody></table><ul><li>これは私の本です。——話し手の近くにある本を指しています。</li><li>駅はどちらですか。——駅の方向を丁寧に尋ねています。</li></ul><p>こちら／そちら／あちら／どちら は、文脈によって人や選択肢を丁寧に指す場合もあります。</p><h2 id="n1-に-n2-が-あります-います" tabindex="-1">N1 に N2 が あります／います <a class="header-anchor" href="#n1-に-n2-が-あります-います" aria-label="Permalink to &quot;N1 に N2 が あります／います&quot;">​</a></h2><p><strong>規則：</strong> N1 という場所に N2 が存在することを初めて伝える形です。に は場所、が は存在するものを示します。物や植物には <strong>あります</strong>、人や動物には <strong>います</strong> を使います。</p><ul><li>机の上に本があります。——机の上に本があることを伝えています。</li><li>教室に学生がいます。——教室に学生がいることを伝えています。</li></ul><p>所有を表す場合は、人を存在の基準にすることもできます：私には兄がいます。——自分に兄がいるという意味です。</p><h2 id="n1-には-n2-が-あります-います" tabindex="-1">N1 には N2 が あります／います <a class="header-anchor" href="#n1-には-n2-が-あります-います" aria-label="Permalink to &quot;N1 には N2 が あります／います&quot;">​</a></h2><p><strong>規則：</strong> には は場所を示す に と、話題・対比を示す は の組み合わせです。N1 を話題の範囲として示し、別の場所や人との対比を含むことがあります。N2 に合わせて あります／います を選びます。</p><ul><li>この町には大きな公園があります。——この町について、公園があると述べています。</li><li>私のクラスには留学生がいます。——自分のクラスについて、留学生がいると述べています。</li></ul><p><strong>教室に学生がいます</strong> は学生の存在を伝え、<strong>教室には学生がいます</strong> は「教室には」と場所をより強く話題にします。</p><h2 id="n1-は-n2-に-あります-います" tabindex="-1">N1 は N2 に あります／います <a class="header-anchor" href="#n1-は-n2-に-あります-います" aria-label="Permalink to &quot;N1 は N2 に あります／います&quot;">​</a></h2><p><strong>規則：</strong> すでに分かっている N1 が<strong>どこにある／いるか</strong>を述べる形です。は は既知の話題、に は場所を示します。N1 に合わせて あります／います を選びます。</p><ul><li>本は机の上にあります。——その本の場所を伝えています。</li><li>先生は職員室にいます。——先生の居場所を伝えています。</li></ul><p><strong>机の上に本があります</strong> は本の存在を新しく伝え、<strong>本は机の上にあります</strong> は既知の本の場所を伝えます。</p><h2 id="過去形-名詞述語" tabindex="-1">過去形：名詞述語 <a class="header-anchor" href="#過去形-名詞述語" aria-label="Permalink to &quot;過去形：名詞述語&quot;">​</a></h2><p><strong>規則：</strong> 丁寧体の名詞文では です を <strong>でした</strong> に変えます。否定の過去形は <strong>ではありませんでした</strong> で、会話では <strong>じゃありませんでした</strong> とも言います。ナ形容詞の述語にも同じ形を使います。</p><table tabindex="0"><thead><tr><th>意味</th><th>文型</th><th>例文</th></tr></thead><tbody><tr><td>過去の肯定</td><td>A は B でした</td><td>昨日は休みでした。——昨日が休みだったことを述べています。</td></tr><tr><td>過去の否定</td><td>A は B ではありませんでした</td><td>昨日は休みではありませんでした。——昨日が休みではなかったことを述べています。</td></tr></tbody></table><p>普通体では <strong>だった</strong>、<strong>ではなかった</strong>（または <strong>じゃなかった</strong>）を使います：昨日は休みだった。</p><h2 id="過去形-動詞述語" tabindex="-1">過去形：動詞述語 <a class="header-anchor" href="#過去形-動詞述語" aria-label="Permalink to &quot;過去形：動詞述語&quot;">​</a></h2><p><strong>規則：</strong> 丁寧体では、肯定の <strong>～ます</strong> を <strong>～ました</strong> に、否定の <strong>～ません</strong> を <strong>～ませんでした</strong> に変えます。普通体の過去形は動詞の種類によって変わるため、ます を単純に た に置き換えることはできません。</p><table tabindex="0"><thead><tr><th>意味</th><th>丁寧体</th><th>普通体</th></tr></thead><tbody><tr><td>過去の肯定</td><td>昨日、映画を見ました。——昨日見たことを述べています。</td><td>昨日、映画を見た。</td></tr><tr><td>過去の否定</td><td>昨日、映画を見ませんでした。——昨日見なかったことを述べています。</td><td>昨日、映画を見なかった。</td></tr></tbody></table><p>例えば、行きます → 行きました → 行った、食べます → 食べました → 食べた です。</p><h2 id="疑問詞と-が" tabindex="-1">疑問詞と が <a class="header-anchor" href="#疑問詞と-が" aria-label="Permalink to &quot;疑問詞と が&quot;">​</a></h2><p><strong>規則：</strong> 「誰が／何が」主語なのかを尋ねるとき、疑問詞には が を付けます。答えでも が を使って主語を特定することが一般的です。ただし、すでに分かっている話題として述べたり対比したりする場合は は も使えます。「が で尋ねたら必ず が で答える」という決まりではありません。</p><ul><li>誰が来ましたか。——来た人を尋ねています。</li><li>田中さんが来ました。——来た人を特定しています。</li><li>何がありますか。——存在するものを尋ねています。</li><li>机の上に本があります。——本があると答えています。</li></ul><h2 id="この-その-あの-どの" tabindex="-1">この／その／あの／どの <a class="header-anchor" href="#この-その-あの-どの" aria-label="Permalink to &quot;この／その／あの／どの&quot;">​</a></h2><p><strong>規則：</strong> これらは名詞を直接修飾する <strong>連体詞</strong> で、後ろに名詞が必要です。この本、その本、あの本、どの本 のように使います。名詞を付けずに物を指すときは、これ／それ／あれ／どれ を使います。</p><ul><li>この本は面白いです。——近くの本について述べています。</li><li>これは面白いです。——名詞を繰り返さず、近くのものを指しています。</li><li>どの本があなたのですか。——本の中から一冊を尋ねています。</li><li>どれがあなたのですか。——名詞を繰り返さずに尋ねています。</li></ul>',42)])])}const b=r(l,[["render",s]]);export{u as __pageData,b as default};
